import urllib.request,json,hashlib,pathlib,concurrent.futures,subprocess,tarfile
root=pathlib.Path('/home/amirreza/Desktop/Projects/Attestara')
work=pathlib.Path('/tmp/attestara-c02'); work.mkdir(exist_ok=True)
out=root/'docs/engineering/resources'; out.mkdir(parents=True,exist_ok=True)
def fetch(url):
 for attempt in range(3):
  try: return urllib.request.urlopen(urllib.request.Request(url,headers={'User-Agent':'Attestara-C02-resource-verification'}),timeout=50).read()
  except Exception:
   if attempt==2: raise
def sha(b): return hashlib.sha256(b).hexdigest()
def snapshot(name,url):
 b=fetch(url); p=out/name;p.write_bytes(b)
 return {'url':url,'path':str(p.relative_to(root)),'sha256':sha(b)},b
def download(name,url,expected=None):
 p=work/name
 if not p.exists(): p.write_bytes(fetch(url))
 b=p.read_bytes(); actual=sha(b)
 if expected and actual!=expected: raise ValueError(name+' CHECKSUM MISMATCH '+actual)
 print(name,actual,len(b),flush=True)
 return {'url':url,'filename':name,'sha256':actual}
def record(id,version,required,source,license,licenseurl,artifact,integrity,build):
 lic,_=snapshot(id+'-LICENSE.txt',licenseurl)
 return {'id':id,'version':version,'required':required,'platform':'linux-x64','source_url':source,'license':{'expression':license,**lic},'redistribution':'Retain upstream copyright, license and required notices; see the pinned license text. No license of the Attestara source is changed.','artifact':artifact,'integrity':integrity,'source_build':build}
def provider(id,repo):
 rel=json.loads(fetch('https://api.github.com/repos/'+repo+'/releases/latest'))
 tag=rel['tag_name'];v=tag.removeprefix('v');commit=json.loads(fetch(f'https://api.github.com/repos/{repo}/commits/{tag}'))['sha']
 name='opa_linux_amd64_static' if id=='opa' else f'{id}_{v}_linux_amd64.tar.gz'
 asset=next(x for x in rel['assets'] if x['name']==name)
 checksumname=name+'.sha256' if id=='opa' else f'{id}_{v}_checksums.txt'
 checksumasset=next(x for x in rel['assets'] if x['name']==checksumname)
 integ,b=snapshot(id+'-checksums.txt',checksumasset['browser_download_url'])
 expected=asset['digest'].split(':')[1]
 if not any(expected in line and name in line for line in b.decode().splitlines()): raise ValueError('published checksums disagree '+id)
 artifact=download(name,asset['browser_download_url'],expected)
 source=download(id+'-source.tar.gz',f'https://codeload.github.com/{repo}/tar.gz/{commit}')
 recipe,rb=snapshot(id+'-BUILD.txt',f'https://raw.githubusercontent.com/{repo}/{commit}/Makefile')
 build={'source_commit':commit,'archive':source,'recipe':recipe,'commands':['GOTOOLCHAIN=local go build -mod=readonly -trimpath -o '+id+' '+('.' if id=='opa' else './cmd/'+id)],'verification':'Recipe inspected at the pinned source; actual build result is recorded in C02 evidence.'}
 return record(id,v,False,rel['html_url'],'Apache-2.0',f'https://raw.githubusercontent.com/{repo}/{commit}/LICENSE',artifact,{'format':'sha256sum',**integ},build)
def go():
 metadata,b=snapshot('go-release.json','https://go.dev/dl/?mode=json')
 release=json.loads(b)[0];v=release['version'];f=next(x for x in release['files'] if x['filename']==v+'.linux-amd64.tar.gz')
 commitmeta,commitbytes=snapshot('go-source-commit.json','https://api.github.com/repos/golang/go/commits/'+v)
 commit=json.loads(commitbytes)['sha']
 artifact=download('go-source.tar.gz','https://codeload.github.com/golang/go/tar.gz/'+commit)
 build={'source_commit':commit,'archive':artifact,'recipe_url':'https://go.dev/doc/install/source','commands':['cd src && GOROOT_BOOTSTRAP=/path/to/go1.26.2 GOMAXPROCS=2 ./make.bash'],'verification':'Pinned official source archive; actual build result is recorded in C02 evidence.'}
 resource=record('go',v.removeprefix('go'),True,'https://go.dev/dl/#'+v,'BSD-3-Clause',f'https://raw.githubusercontent.com/golang/go/{commit}/LICENSE',artifact,{'format':'git-commit','source_commit':commit,**commitmeta},build)
 resource['prebuilt_alternative']={'url':'https://go.dev/dl/'+f['filename'],'sha256':f['sha256'],'availability':'HTTP 404 observed on 2026-10-17; use the pinned source-build route','official_metadata':metadata}
 return resource
def node():
 v='24.19.0';name=f'node-v{v}-linux-x64.tar.xz';base=f'https://nodejs.org/dist/v{v}/'
 meta,b=snapshot('node-SHASUMS256.txt',base+'SHASUMS256.txt');expected=next(l.split()[0] for l in b.decode().splitlines() if l.split()[-1]==name)
 artifact=download(name,base+name,expected)
 srcname=f'node-v{v}.tar.xz';srcsha=next(l.split()[0] for l in b.decode().splitlines() if l.split()[-1]==srcname)
 build={'archive':{'url':base+srcname,'filename':srcname,'sha256':srcsha},'recipe_url':f'https://github.com/nodejs/node/blob/v{v}/BUILDING.md','commands':['./configure','make -j2'],'verification':'Official pinned BUILDING.md is the source-build recipe; no new Node build claimed.'}
 return record('node',v,True,base,'MIT AND bundled notices',f'https://raw.githubusercontent.com/nodejs/node/v{v}/LICENSE',artifact,{'format':'sha256sum',**meta},build)
def npm():
 meta,b=snapshot('npm-release.json','https://registry.npmjs.org/npm/11.9.0');d=json.loads(b)
 artifact=download('npm-11.9.0.tgz',d['dist']['tarball']);artifact['integrity']=d['dist']['integrity']
 import base64
 if 'sha512-'+base64.b64encode(hashlib.sha512((work/artifact['filename']).read_bytes()).digest()).decode()!=artifact['integrity']: raise ValueError('npm SRI mismatch')
 return record('npm','11.9.0',True,'https://github.com/npm/cli/releases/tag/v11.9.0','Artistic-2.0', 'https://raw.githubusercontent.com/npm/cli/v11.9.0/LICENSE',artifact,{'format':'npm-dist',**meta},{'recipe_url':'https://github.com/npm/cli/tree/v11.9.0','commands':['node bin/npm-cli.js --version'],'verification':'npm is distributed as JavaScript source; the integrity-checked tarball is directly runnable.'})
def spec(id,repo,version,commit,license):
 meta,b=snapshot(id+'-REFERENCE.md',f'https://raw.githubusercontent.com/{repo}/{commit}/README.md')
 artifact=download(id+'-source.tar.gz',f'https://codeload.github.com/{repo}/tar.gz/{commit}')
 return record(id,version,False,f'https://github.com/{repo}/tree/{commit}',license,f'https://raw.githubusercontent.com/{repo}/{commit}/LICENSE',artifact,{'format':'pinned-source','source_commit':commit,**meta},{'not_applicable':'Normative specification source, not executable code. Adapters and schema validation are later tasks.'})
tasks=[go,node,npm,lambda:provider('opa','open-policy-agent/opa'),lambda:provider('syft','anchore/syft'),lambda:provider('grype','anchore/grype'),lambda:spec('cyclonedx','CycloneDX/specification','1.7','349314a9d7671d7d2ca5b711a725f49a73979da6','Apache-2.0'),lambda:spec('spdx','spdx/spdx-spec','3.0','f148837fa65ea5ce88c65531480404453c15fd26','Community-Spec-1.0 AND CC-BY-3.0')]
with concurrent.futures.ThreadPoolExecutor(max_workers=8) as pool:
 resources=list(pool.map(lambda f:f(),tasks))
(work/'resources.json').write_text(json.dumps(resources,indent=2)+'\n')
